class bone;

class po {
public:
  float m[4][4];
};

void fast_po_mul(po&, const po&, const po&);

class link_interface {
public:
  bone* my_parent;
  bone* get_parent() const { return my_parent; }
};

class signaller {
public:
  virtual ~signaller();
};

class bone : public signaller {
protected:
  po my_rel_po;
  po* my_abs_po;
  po* my_handed_abs_po;
  int bone_id;
  void* my_sector;
  int flip_axis;
  bool is_part_of_skeleton;
  link_interface* my_link_interface;

public:
  bool has_link_ifc() const { return (my_link_interface != 0); }
  link_interface* link_ifc() const { return my_link_interface; }
  const po& get_rel_po() const { return my_rel_po; }
  const po& get_abs_po() const { return *my_abs_po; }
  void update_abs_po_reverse();
};

void bone::update_abs_po_reverse()
    {
      if (has_link_ifc())
      {
        if (link_ifc()->my_parent)
        {
          link_ifc()->my_parent->update_abs_po_reverse();

          fast_po_mul(*my_abs_po, get_rel_po(), link_ifc()->get_parent()->get_abs_po());
//          *my_abs_po = get_rel_po() * link_ifc()->my_parent->get_abs_po();
        }
        else
          *my_abs_po = get_rel_po();
      }
    }
